def _orbit_track(radius, dur, reverse, phase, count, index):
    cx, cy = ORBIT_W / 2.0, ORBIT_H / 2.0
    ry = radius * ORBIT_TILT
    direction = -1.0 if reverse else 1.0
    base = math.radians(phase) + (2 * math.pi * index) / count
    pts, depth = [], []
    for step in range(ORBIT_SAMPLES + 1):
        angle = base + direction * 2 * math.pi * (step / float(ORBIT_SAMPLES))
        pts.append((cx + radius * math.cos(angle), cy + ry * math.sin(angle)))
        depth.append((math.sin(angle) + 1.0) / 2.0)
    return pts, depth


def _orbit_icon_defs():
    parts = ['<defs>']
    for slug, item in ORBIT_ICONS.items():
        parts.append('<g id="i-%s"><path d="%s"/></g>' % (slug, item[2]))
    parts.append('</defs>')
    return "".join(parts)


def _orbit_icon_css():
    rules = ["  .chip { fill: #f6f8fa; stroke: #d0d7de; }"]
    dark = ["    .chip { fill: #1c2128; stroke: #373e47; }"]
    for slug, item in ORBIT_ICONS.items():
        rules.append("  .ic-%s { fill: #%s; }" % (slug, item[0]))
        if item[1] != item[0]:
            dark.append("    .ic-%s { fill: #%s; }" % (slug, item[1]))
    css = "\n".join(rules)
    if dark:
        css += "\n  @media (prefers-color-scheme: dark) {\n" + "\n".join(dark) + "\n  }"
    return css


def _orbit_body(label, slug, weight):
    box = ICON_BOX[weight]
    if slug is None:
        height = box * 0.78
        width = 18 + 7.4 * len(label)
        font = 9 + weight
        return (
            '<rect class="chip" x="%.1f" y="%.1f" width="%.1f" height="%.1f" '
            'rx="%.1f" stroke-width="1"/>'
            '<text class="t fg" x="0" y="%.1f" text-anchor="middle" '
            'font-size="%d">%s</text>'
            % (-width / 2, -height / 2, width, height, height / 2,
               font * 0.36, font, label)
        )
    card = box + 12
    scale = box / 24.0
    return (
        '<rect class="chip" x="%.1f" y="%.1f" width="%d" height="%d" rx="10" '
        'stroke-width="1"/>'
        '<use href="#i-%s" xlink:href="#i-%s" class="ic-%s" '
        'transform="translate(%.1f,%.1f) scale(%.4f)"/>'
        % (-card / 2.0, -card / 2.0, card, card, slug, slug, slug,
           -box / 2.0, -box / 2.0, scale)
    )


def _orbit_item(ring, label, slug, weight, near_side):
    radius, dur, reverse, phase = ORBIT_RINGS[ring]
    siblings = [i for i in ORBIT_ITEMS if i[0] == ring]
    index = siblings.index((ring, label, slug, weight))
    pts, depth = _orbit_track(radius, dur, reverse, phase, len(siblings), index)

    moves, fades, scales = [], [], []
    for step, point in enumerate(pts):
        t = depth[step]
        moves.append("%.1f %.1f" % point)
        visible = t >= 0.5 if near_side else t <= 0.5
        opacity = ORBIT_FAR_OPACITY + (1.0 - ORBIT_FAR_OPACITY) * t
        fades.append("%.3f" % (opacity if visible else 0.0))
        size = ORBIT_FAR_SCALE + (1.0 - ORBIT_FAR_SCALE) * t
        scales.append("%.3f" % size)

    return (
        '<g><animateTransform attributeName="transform" type="translate" '
        'values="%s" dur="%ds" repeatCount="indefinite" calcMode="linear"/>'
        '<g opacity="0">'
        '<animate attributeName="opacity" values="%s" dur="%ds" '
        'repeatCount="indefinite" calcMode="linear"/>'
        '<animateTransform attributeName="transform" type="scale" values="%s" '
        'dur="%ds" repeatCount="indefinite" calcMode="linear"/>'
        '%s</g></g>'
        % (";".join(moves), dur, ";".join(fades), dur, ";".join(scales), dur,
           _orbit_body(label, slug, weight))
    )


def _orbit_core():
    cx, cy = ORBIT_W / 2.0, ORBIT_H / 2.0
    parts = []
    for index in range(3):
        parts.append(
            '<ellipse cx="%.1f" cy="%.1f" rx="22" ry="%.1f" fill="none" '
            'stroke="%s" stroke-width="1.5" opacity="0">'
            '<animate attributeName="rx" values="22;66" dur="3.6s" begin="%.1fs" '
            'repeatCount="indefinite"/>'
            '<animate attributeName="ry" values="%.2f;%.2f" dur="3.6s" '
            'begin="%.1fs" repeatCount="indefinite"/>'
            '<animate attributeName="opacity" values="0.55;0" dur="3.6s" '
            'begin="%.1fs" repeatCount="indefinite"/>'
            '</ellipse>'
            % (cx, cy, 22 * ORBIT_TILT, ACCENT, index * 1.2,
               22 * ORBIT_TILT, 66 * ORBIT_TILT, index * 1.2, index * 1.2)
        )
    parts.append(
        '<ellipse cx="%.1f" cy="%.1f" rx="26" ry="%.1f" fill="%s" opacity="0.16">'
        '<animate attributeName="rx" values="24;30;24" dur="4s" '
        'repeatCount="indefinite"/>'
        '<animate attributeName="ry" values="%.2f;%.2f;%.2f" dur="4s" '
        'repeatCount="indefinite"/></ellipse>'
        % (cx, cy, 26 * ORBIT_TILT, ACCENT,
           24 * ORBIT_TILT, 30 * ORBIT_TILT, 24 * ORBIT_TILT)
    )
    parts.append(
        '<circle cx="%.1f" cy="%.1f" r="20" fill="%s"/>' % (cx, cy, ACCENT)
    )
    parts.append(
        '<text class="t" x="%.1f" y="%.1f" text-anchor="middle" font-size="10" '
        'font-weight="700" fill="#ffffff">smit</text>' % (cx, cy + 3.5)
    )
    return "".join(parts)


def write_orbit():
    cx, cy = ORBIT_W / 2.0, ORBIT_H / 2.0
    parts = []
    parts.append(
        '<svg xmlns="http://www.w3.org/2000/svg" '
        'xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 %d %d" '
        'width="%d" height="%d" role="img" aria-label="Tech stack orbit">'
        % (ORBIT_W, ORBIT_H, ORBIT_W, ORBIT_H)
    )
    parts.append(
        "<style>%s\n%s\n  .t{font-family:%s}</style>"
        % (THEME_CSS, _orbit_icon_css(), FONT)
    )
    parts.append(_orbit_icon_defs())

    for radius, _dur, _rev, _phase in ORBIT_RINGS:
        parts.append(
            '<ellipse cx="%.1f" cy="%.1f" rx="%d" ry="%.1f" fill="none" '
            'class="grid" stroke-width="1" stroke-dasharray="3 6" '
            'opacity="0.7"/>' % (cx, cy, radius, radius * ORBIT_TILT)
        )

    for item in sorted(ORBIT_ITEMS, key=lambda i: -i[0]):
        parts.append(_orbit_item(*item, near_side=False))

    parts.append(_orbit_core())

    for item in sorted(ORBIT_ITEMS, key=lambda i: i[0]):
        parts.append(_orbit_item(*item, near_side=True))

    parts.append("</svg>")
    (OUT / "orbit.svg").write_text("\n".join(parts), encoding="utf-8")


MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
               "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def write_commit_race(totals):
    w, h = 900, 280
    left, right = 44, 24
    top, bottom = 46, 52
    plot_w = w - left - right
    plot_h = h - top - bottom
    slot = plot_w / 12.0
    bar_w = slot * 0.56

    peak = 1
    for _key, value in totals:
        if value > peak:
            peak = value

    parts = []
    parts.append(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" '
        'width="%d" height="%d" role="img" aria-label="Contributions per month">'
        % (w, h, w, h)
    )
    parts.append("<style>%s .t{font-family:%s}</style>" % (THEME_CSS, FONT))
    parts.append(
        '<defs><linearGradient id="bar" x1="0" y1="1" x2="0" y2="0">'
        '<stop offset="0%%" stop-color="%s" stop-opacity="0.55"/>'
        '<stop offset="100%%" stop-color="%s"/></linearGradient></defs>'
        % (ACCENT, ACCENT_2)
    )

    parts.append(
        '<text class="t fg" x="%d" y="26" font-size="15" font-weight="700">'
        'Contributions &#183; last 12 months</text>' % left
    )

    for step in range(4):
        y = top + (plot_h / 3.0) * step
        value = int(round(peak - (peak / 3.0) * step))
        parts.append(
            '<line x1="%d" y1="%.1f" x2="%d" y2="%.1f" class="grid" '
            'stroke-width="1" opacity="0.5"/>' % (left, y, w - right, y)
        )
        parts.append(
            '<text class="t muted" x="%d" y="%.1f" font-size="10" '
            'text-anchor="end">%d</text>' % (left - 8, y + 3, value)
        )

    for index, item in enumerate(totals):
        key, value = item
        bar_h = (value / float(peak)) * plot_h
        x = left + slot * index + (slot - bar_w) / 2.0
        y = top + plot_h - bar_h
        delay = 0.15 + index * 0.07
        parts.append(
            '<rect x="%.1f" y="%.1f" width="%.1f" height="0" rx="4" fill="url(#bar)">'
            '<animate attributeName="height" from="0" to="%.1f" begin="%.2fs" '
            'dur="0.9s" fill="freeze" calcMode="spline" keySplines="0.2 0 0 1" '
            'keyTimes="0;1"/>'
            '<animate attributeName="y" from="%.1f" to="%.1f" begin="%.2fs" '
            'dur="0.9s" fill="freeze" calcMode="spline" keySplines="0.2 0 0 1" '
            'keyTimes="0;1"/></rect>'
            % (x, top + plot_h, bar_w, bar_h, delay, top + plot_h, y, delay)
        )
        parts.append(
            '<text class="t fg" x="%.1f" y="%.1f" font-size="11" '
            'text-anchor="middle" opacity="0">%d'
            '<animate attributeName="opacity" from="0" to="1" begin="%.2fs" '
            'dur="0.5s" fill="freeze"/></text>'
            % (x + bar_w / 2.0, y - 7, value, delay + 0.7)
        )
        month_index = int(key[5:7]) - 1
        parts.append(
            '<text class="t muted" x="%.1f" y="%d" font-size="11" '
            'text-anchor="middle">%s</text>'
            % (x + bar_w / 2.0, top + plot_h + 20, MONTH_NAMES[month_index])
        )

    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    parts.append(
        '<text class="t muted" x="%d" y="%d" font-size="10" text-anchor="end">'
        'generated %s</text>' % (w - right, h - 12, stamp)
    )

    parts.append("</svg>")
    (OUT / "commit-race.svg").write_text("\n".join(parts), encoding="utf-8")


def write_divider():
    w, h = 900, 12
    parts = []
    parts.append(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 %d %d" '
        'width="%d" height="%d" role="presentation">' % (w, h, w, h)
    )
    parts.append(
        '<defs><linearGradient id="d" x1="0" y1="0" x2="1" y2="0">'
        '<stop offset="0%%" stop-color="%s" stop-opacity="0"/>'
        '<stop offset="50%%" stop-color="%s" stop-opacity="0.9"/>'
        '<stop offset="100%%" stop-color="%s" stop-opacity="0"/>'
        '<animateTransform attributeName="gradientTransform" type="translate" '
        'from="-1 0" to="1 0" dur="5s" repeatCount="indefinite"/>'
        '</linearGradient></defs>' % (ACCENT, ACCENT_2, ACCENT_3)
    )
    parts.append(
        '<rect x="0" y="5" width="%d" height="2" rx="1" fill="#888" '
        'opacity="0.18"/>' % w
    )
    parts.append('<rect x="0" y="4.5" width="%d" height="3" rx="1.5" fill="url(#d)"/>' % w)
    parts.append("</svg>")
    (OUT / "divider.svg").write_text("\n".join(parts), encoding="utf-8")


def main():
    OUT.mkdir(exist_ok=True)
    write_header()
    write_orbit()
    write_divider()

    days = fetch_calendar()
    if days:
        write_commit_race(monthly_totals(days))
    else:
        target = OUT / "commit-race.svg"
        if not target.exists():
            write_commit_race(monthly_totals([]))
        else:
            print("keeping existing commit-race.svg")

    print("done")


if __name__ == "__main__":
    main()
